@push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const draw=(id,data,keys,colors)=>{const canvas=document.getElementById(id);if(!canvas)return;const ctx=canvas.getContext('2d'),ratio=window.devicePixelRatio||1,w=canvas.clientWidth||500,h=170;canvas.width=w*ratio;canvas.height=h*ratio;ctx.scale(ratio,ratio);ctx.strokeStyle='#e5e7eb';ctx.beginPath();ctx.moveTo(32,10);ctx.lineTo(32,h-28);ctx.lineTo(w-8,h-28);ctx.stroke();if(!data.length){ctx.fillStyle='#64748b';ctx.font='14px Arial';ctx.fillText('Belum ada data pada periode ini.',48,85);return;}const max=Math.max(...data.flatMap(x=>keys.map(k=>Number(x[k]||0))),1),step=(w-52)/data.length;data.forEach((item,i)=>{const x=42+i*step;keys.forEach((key,j)=>{const value=Number(item[key]||0),bar=(value/max)*(h-55);ctx.fillStyle=colors[j];ctx.fillRect(x+j*Math.max(12,step/keys.length-4),h-29-bar,Math.max(10,step/keys.length-8),bar);});ctx.fillStyle='#172033';ctx.font='10px Arial';ctx.fillText(item.period,x,h-10);});};draw('owner-sales-chart',@json($monthlySales),['units'],['#ed1c24']);draw('owner-booking-sales-chart',@json($bookingSales),['bookings','sales'],['#172033','#ed1c24']);draw('owner-service-chart',@json($serviceTrends),['bookings','completed'],['#64748b','#ed1c24']);});</script>@endpush
